import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.BS0bAV7E.js";const g=JSON.parse('{"title":"End-to-end suites","description":"","frontmatter":{},"headers":[],"relativePath":"dev/e2e-suites.md","filePath":"dev/e2e-suites.md"}'),n={name:"dev/e2e-suites.md"};function i(r,e,l,h,c,d){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="end-to-end-suites" tabindex="-1">End-to-end suites <a class="header-anchor" href="#end-to-end-suites" aria-label="Permalink to &quot;End-to-end suites&quot;">​</a></h1><p>The deep tests that gate a release. All of them drive a real QEMU boot through pexpect on the serial console.</p><h2 id="regression-battery-tools-run-fix4-regression-py" tabindex="-1">Regression battery - tools/run_fix4_regression.py <a class="header-anchor" href="#regression-battery-tools-run-fix4-regression-py" aria-label="Permalink to &quot;Regression battery - tools/run_fix4_regression.py&quot;">​</a></h2><p>28 checks: boot banner, boot-complete, exception self-test 3/3, command count 233, uname tag forms, heaptest, fstest, cryptotest, crashlog, l1test, and every <code>run &lt;userprog&gt;</code> (hello, fork, exec, pipe, signal, select, mmap variants, dynamic linking: so_test, dlsym_test, pie_test, reloc_test, p3, g6, g7...).</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 tools/run_fix4_regression.py build/opencube.iso out.log</span></span></code></pre></div><h2 id="watchdog-logging-health-e2e-tools-wp12-watchdog-logging-e2e-py" tabindex="-1">Watchdog/logging/health E2E - tools/wp12_watchdog_logging_e2e.py <a class="header-anchor" href="#watchdog-logging-health-e2e-tools-wp12-watchdog-logging-e2e-py" aria-label="Permalink to &quot;Watchdog/logging/health E2E - tools/wp12_watchdog_logging_e2e.py&quot;">​</a></h2><p>14 scenarios (S1-S14). The two that matter most:</p><ul><li><strong>S12 (Intel TCO)</strong>: q35 + <code>-no-reboot</code>; asserts the TCO discovery line (<code>Intel TCO found: PMBASE=... TCOBASE=...</code>), arms the watchdog, starves it, asserts the REAL reset and the second boot.</li><li><strong>S13 (ACPI WDAT)</strong>: same shape through the WDAT table entries.</li></ul><p>Plus klog write/flush/rotate/filter chains (threshold 4096 -&gt; <code>kernel.log</code> + <code>kernel.log.1</code> real generation), watchdog policy kill (a starver task is killed with a log record while the kernel survives), and health (JSON export validity, 3-spinner CPU alarm <code>CPU-LOCKED</code> with the kernel alive).</p><h2 id="ssh-e2e" tabindex="-1">SSH E2E <a class="header-anchor" href="#ssh-e2e" aria-label="Permalink to &quot;SSH E2E&quot;">​</a></h2><p>The in-guest <code>sshd</code> needs host/client keys on the /etc volume - the suite (or you) seed them with <code>host_keygen_etc</code>. Then a paramiko client from the host performs the full login + session + command round-trip: 5/5 ALL PASS is the gate.</p><h2 id="https-e2e" tabindex="-1">HTTPS E2E <a class="header-anchor" href="#https-e2e" aria-label="Permalink to &quot;HTTPS E2E&quot;">​</a></h2><p><code>wget https://&lt;reference-host&gt;/</code> from inside the guest against a reference TLS server: handshake OK, GET received, body saved, close_notify clean. 7 checks (handshake, cert chain, body bytes, close semantics, timings).</p><h2 id="the-etc-volume-fixture" tabindex="-1">The /etc volume fixture <a class="header-anchor" href="#the-etc-volume-fixture" aria-label="Permalink to &quot;The /etc volume fixture&quot;">​</a></h2><p>SSH and HTTPS suites assume a seeded <code>etc.img</code>. Build it once per test cycle:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make etc.img          # 32 MiB FAT32 + opencube.conf</span></span>
<span class="line"><span># then inside a first boot: host_keygen_etc (writes SSH keys)</span></span></code></pre></div><p>The QEMU <code>run-*</code> make targets attach it automatically.</p>`,17)])])}const u=t(n,[["render",i]]);export{g as __pageData,u as default};
